fn put64(out:&mut[u8],pos:&mut usize,x:i64){out[*pos..*pos+8].copy_from_slice(&x.to_le_bytes());*pos+=8;}
#[no_mangle]pub unsafe extern "C" fn swap_nodes(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<3{return -1;}let nn=*input;if nn<0||nn>64||length!=nn as usize+3{return -1;}let n=nn as usize;let vals=std::slice::from_raw_parts(input.add(1),n);if vals.iter().any(|&x|x<i32::MIN as i64||x>i32::MAX as i64){return -1;}let a=*input.add(1+n);let b=*input.add(2+n);if a<i32::MIN as i64||a>i32::MAX as i64||b<i32::MIN as i64||b>i32::MAX as i64{return -1;}let need=8+8*n;if output.is_null()||capacity<need{return -2;}let mut ia=n;let mut ib=n;if a!=b{for i in 0..n{if ia==n&&vals[i]==a{ia=i;}if ib==n&&vals[i]==b{ib=i;}}}let bytes=std::slice::from_raw_parts_mut(output,need);let mut pos=0;put64(bytes,&mut pos,nn);for i in 0..n{let mut x=vals[i];if ia<n&&ib<n{if i==ia{x=b;}else if i==ib{x=a;}}put64(bytes,&mut pos,x);}pos as i64}
